mapper.insert:
insert into SHOP_ORDER (
  ID, ORDER_NO, USER_ID, TOTAL_AMOUNT, STATUS,
  RECEIVER_NAME, RECEIVER_PHONE, RECEIVER_ADDRESS, REMARK,
  PAY_TIME, CREATE_TIME, UPDATE_TIME
) values (
  #{id}, #{orderNo}, #{userId}, #{totalAmount}, #{status},
  #{receiverName}, #{receiverPhone}, #{receiverAddress}, #{remark},
  #{payTime}, #{createTime}, #{updateTime}
)

mapper.select:
select ID, ORDER_ID, PRODUCT_ID, PRODUCT_NAME, PRICE, QUANTITY, SUBTOTAL
from SHOP_ORDER_ITEM
where ORDER_ID = #{orderId}

mapper.update:
update SHOP_ORDER
set STATUS = #{status}, UPDATE_TIME = #{updateTime}
    , PAY_TIME = #{payTime}
where ID = #{id}

mapper.select:
select * from (
  select t.*, ROWNUM rn from (
    select ID, ORDER_NO, USER_ID, TOTAL_AMOUNT, STATUS, RECEIVER_NAME, RECEIVER_PHONE,
           RECEIVER_ADDRESS, REMARK, PAY_TIME, CREATE_TIME, UPDATE_TIME
    from SHOP_ORDER

    order by CREATE_TIME desc
  ) t where ROWNUM <= #{offset} + #{limit}
) where rn > #{offset}
